    tasks.push_back(task);
  }

  return tasks;
}

Status CollectionImpl::execute_compact_task(
    std::vector<SegmentTask::Ptr> &tasks) const {
  Status s;
  for (auto &task : tasks) {
    s = SegmentHelper::Execute(task);
    if (!s.ok()) {
      return s;
    }
  }

  return Status::OK();
}

